document.addEventListener("DOMContentLoaded",()=>{const e=document,t=e.querySelector("#modpress-enable-integrations"),n=e.querySelector("#modpress-integration-switches");if(t&&n){const e=()=>{const e=t.checked;n.classList.toggle("d-none",!e),n.querySelectorAll('input[type="checkbox"]').forEach(t=>{t.disabled=!e})};t.addEventListener("change",e),e()}const s=e.querySelector("#modpress-reset-scope"),o=e.querySelector("#modpress-reset-plugins");if(!s||!o)return;const c=()=>{const e="plugins"===s.value;o.hidden=!e,o.querySelectorAll('input[type="checkbox"]').forEach(t=>{t.disabled=!e})};s.addEventListener("change",c),c()});